#ifndef SCAMP_CORE_H
#define SCAMP_CORE_H

#include <cstdint>

typedef uint64_t nexthop_t;
static const nexthop_t LPM_INVALID_NH = (nexthop_t)-1;

// A 22-bit BMP field carries a forwarding hop value; this value denotes null.
static const uint32_t BMP_NULL = 4194303u;
// Forwarding hops never use the null sentinel.
