static const int RAM_NUM = 11;   // stages 0..10, stage 0 is the tail, 10 the head
static const int MAX_STAGE = 10;
static const int FRONT16_BITS = 16;
static const int FRONT64_BITS = 64;

struct ip6_t {
    uint64_t hi;
    uint64_t lo;
};

inline bool operator==(const ip6_t& a, const ip6_t& b) { return a.hi == b.hi && a.lo == b.lo; }
inline bool operator!=(const ip6_t& a, const ip6_t& b) { return !(a == b); }

// MSB-first bit of a 128-bit address (bit 0 is the MSB of hi).
inline int ipbit(const ip6_t& a, int p) {
    return p < 64 ? (int)((a.hi >> (63 - p)) & 1) : (int)((a.lo >> (127 - p)) & 1);
}

// Extract n bits (n <= 6) starting at MSB-first position p; past-bit-128 reads zero.
inline uint64_t extract_bits(const ip6_t& a, int p, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; ++i) {
        v <<= 1;
        if (p + i < 128) v |= (uint64_t)ipbit(a, p + i);
    }
    return v;
}

// Set n bits at MSB-first position p to the low n bits of v.
inline void set_bits(ip6_t& a, int p, int n, uint64_t v) {
    for (int i = 0; i < n; ++i) {
        int bit = (int)((v >> (n - 1 - i)) & 1);
        int q = p + i;
        if (q < 64) {
            uint64_t m = 1ULL << (63 - q);
            if (bit) a.hi |= m; else a.hi &= ~m;
        } else {
            uint64_t m = 1ULL << (127 - q);
            if (bit) a.lo |= m; else a.lo &= ~m;
        }
    }
}

inline ip6_t mask_address(const ip6_t& a, int len) {
    ip6_t r = a;
    if (len >= 128) return r;
    if (len == 64) { r.lo = 0; return r; }
    if (len > 64) { int s = 128 - len; r.lo = (r.lo >> s) << s; return r; }
    if (len <= 0) { r.hi = 0; r.lo = 0; return r; }
    int s = 64 - len;
    r.hi = (r.hi >> s) << s;
    r.lo = 0;
    return r;
}

// Does prefix (a,len) cover the whole region of addresses sharing the first
// `len` bits with b?  (i.e. is (a,len) a prefix of (b,*).)
