inline bool same_prefix(const ip6_t& a, const ip6_t& b, int len) {
    ip6_t ma = mask_address(a, len);
    ip6_t mb = mask_address(b, len);
    return ma.hi == mb.hi && ma.lo == mb.lo;
}

inline uint64_t count_ones_before(uint64_t bm, int pos) {
    if (pos <= 0) return 0;
    if (pos >= 64) return (uint64_t)__builtin_popcountll(bm);
    return (uint64_t)__builtin_popcountll(bm & ((1ULL << pos) - 1));
}

inline int floor_log2(uint64_t v) { return 63 - __builtin_clzll(v); }

// origin (forest owner) length bounds: 0..16 / 17..64 / 65..128
